function mpc = npcc_ny_lite_s4_generation_aligned_candidate_v1_smoke
%NPCC_NY_LITE_S4_GENERATION_ALIGNED_CANDIDATE_V1
% Auto-generated by run_s4_cost_penalty_calibration_sweep.
case_dir = fileparts(mfilename('fullpath'));
helper_dir = fullfile(case_dir, 'NY_Lite');
addpath(case_dir); addpath(helper_dir);
mpc = loadcase('npcc_ny_lite_s1_acopf_feasible_uncalibrated');
[mpc, ~] = add_ny_downstate_delivery_spine(mpc, 'full');
[mpc, ~] = scale_ny_downstate_delivery_spine_impedance(mpc, 1, struct('include_gilboa_leeds', false));
[mpc, ~] = add_s4_zonal_capability_equivalents(mpc, struct( ...
    'include_zone_j', true, ...
    'zone_j_total_pmax_mw', 3000, ...
    'zone_j_cost_c1', 120, ...
    'zone_j_cost_c2', 0.02, ...
    'equiv_cost_c1', 180, ...
    'equiv_cost_c2', 0.02, ...
    'q_abs_ratio', 0, ...
    'apply_upstate_participation_caps', true, ...
    'abc_cap_factor', 1, ...
    'reclassify_ce_ug', true));
mpc = local_set_s4_zone_costs(mpc, 180, 180, 180, 180, 0.02);
mpc.userdata.ny_lite.s4_cost_penalty_candidate = struct( ...
    'case_id', 'S4_COST_main_grid_J120_E180_F180_G180_K180_CAP1_X1', ...
    'sum_balanced_interface_objective', 30.3393207782175, ...
    'mean_zone_j_equiv_pg_mw', 2692.00426712838, ...
    'mean_s4_equiv_pg_mw', 20.7833100086697);
mpc.userdata.ny_lite.s4_status = 'Generation-aligned cost/participation candidate; interface penalty still post-OPF scored, not embedded nonlinear OPF objective.';
end

function mpc = local_set_s4_zone_costs(mpc, e, f, g, kcost, c2)
devices = mpc.userdata.ny_lite.s4_zonal_capability_equivalents;
for n = 1:numel(devices)
    gi = devices(n).gen_index;
    switch string(devices(n).zone)
        case "E", c1 = e;
        case "F", c1 = f;
        case "G", c1 = g;
        case "K", c1 = kcost;
        otherwise, c1 = f;
    end
    mpc.gencost(gi, 5) = c2;
    mpc.gencost(gi, 6) = c1;
end
end
